// FRACTAL corazón (Heart Fractal) algorithm
function heartFractal(x, y, r, iterations) {
  let offset = 0;
  for (let i = 0; i < iterations; i++) {
    let a = Math.PI / 4 * (i / iterations);
    let b = Math.sin(a + offset);
    let c = r * b;
    x += c * Math.cos(a);
    y += c * Math.sin(a);
    offset += 0.5;
  }
  return [x, y];
}

