using UnityEngine;

public class GemsController : MonoBehaviour
{
    // Constantes
    public const int GRID_SIZE = 8; // Tamaño de la grid
    public const int NUM_GEMS = 5; // Número de tipos de gemas

    // Variables globales
    private Gem[,] gemsGrid; // Grid de gemas
    private int score = 0; // Puntuación actual

    void Start()
    {
        // Inicializa la grid de gemas
        gemsGrid = new Gem[GRID_SIZE, GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++)
        {
            for (int j = 0; j < GRID_SIZE; j++)
            {
                gemsGrid[i, j] = new Gem();
                gemsGrid[i, j].type = Random.Range(1, NUM_GEMS + 1);
                gemsGrid[i, j].position = new Vector2(i, j);
            }
        }
    }

    // Método para cambiar la gema en la posición (i, j)
    public void ChangeGem(int i, int j)
    {
        // Verifica si la gema puede ser cambiada
        if (gemsGrid[i, j].type != 0)
        {
            // Cambia la gema
            gemsGrid[i, j].type = (gemsGrid[i, j].type + 1) % NUM_GEMS;
            // Actualiza la score
            score += gemsGrid[i, j].type * 10;
        }
    }

    // Método para verificar si hay combos
    public void CheckForCombos()
    {
        // Itera sobre la grid de gemas
        for (int i = 0; i < GRID_SIZE; i++)
        {
            for (int j = 0; j < GRID_SIZE; j++)
            {
                // Verifica si hay gemas iguales en las filas
                if (j < GRID_SIZE - 2 && gemsGrid[i, j].type == gemsGrid[i, j + 1].type && gemsGrid[i, j].type == gemsGrid[i, j + 2].type)
                {
                    // Elimina las gemas en la fila
                    for (int k = j; k < GRID_SIZE - 1; k++)
                    {
                        gemsGrid[i, k] = new Gem();
                        gemsGrid[i, k].type = 0;
                    }
                    // Actualiza la score
                    score += gemsGrid[i, j].type * 50;
                }
                // Verifica si hay gemas iguales en las columnas
